import "fmt"

// One definition, any element type.
func First[T any](s []T) T { return s[0] }

func main() {
	fmt.Println(First([]int{10, 20}))       // T=int
	fmt.Println(First([]string{"go", "rs"})) // T=string
	// Output:
	// 10
	// go
}

