package main

import "fmt"

type Number interface{ ~int | ~float64 } // ~ admits named types

type Money int // underlying int -> satisfies ~int

func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x // legal: type set permits +
	}
	return total
}

func main() {
	fmt.Println(Sum([]Money{100, 250}))
	// Output: 350
}

