package main

import (
	"fmt"
	"strconv"
)

func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s)) // pre-size to len(s) — no growth copies
	for i, v := range s {
		out[i] = f(v)        // transform each element
	}
	return out
}

func main() {
	out := Map([]int{1, 2, 3}, strconv.Itoa) // T=int, U=string inferred
	fmt.Println(out)                         // [1 2 3]
}

