package solution

func Filter[T any](s []T, keep func(T) bool) []T {
	out := make([]T, 0, len(s)) // pre-size to the max possible length
	for _, v := range s {
		if keep(v) { // include only matching elements
			out = append(out, v)
		}
	}
	return out
}

