func Contains[T comparable](s []T, v T) bool {
	for _, x := range s {
		if x == v { // comparable permits ==
			return true
		}
	}
	return false
}

func GroupBy[T any, K comparable](items []T, key func(T) K) map[K][]T {
	groups := make(map[K][]T) // key type must be comparable for a map key
	for _, item := range items {
		k := key(item)                    // derive the group key
		groups[k] = append(groups[k], item) // append preserves per-group order
	}
	return groups
}

func Keys[K comparable, V any](m map[K]V) []K {
	out := make([]K, 0, len(m)) // pre-size to avoid reallocations
	for k := range m {
		out = append(out, k)    // collect each key
	}
	return out
}
